import json,hashlib,re,subprocess
from pathlib import Path
D=Path('/Users/tobiasduerschmid/Projects/edbot/output/profiling');ROOT=D.parent.parent
reports={k:json.loads((D/f'cs35l-{name}-v2.json').read_text()) for k,name in [('fixed','studentlike'),('adaptive','adaptive')]}
fixture=json.loads((D/'cs35l-studentlike-cases-20261018.json').read_text())['cases'];review=json.loads((D/'cs35l-semantic-review-v1.json').read_text())
assert [c['case'] for c in reports['fixed']['cases']]==fixture
assert all(d['execution']!='running' for d in reports.values())
repeat_checks=[]
for c in fixture:
 if c['id'].endswith('-repeat'):
  orig=next(x for x in fixture if x['id']==c['id'].removesuffix('-repeat'))
  same=[x['message'] for x in c['turns']]==[x['message'] for x in orig['turns']]
  assert same
  repeat_checks.append({'case':c['id'],'student_messages_identical':same})
source_checks={}
for kind,d in reports.items():
 hashes=d['manifest']['source_sha256']
 def local_path(p):
  q=Path(p)
  return ROOT/q.relative_to('/home/duerschmid/edbot') if q.is_absolute() else ROOT/q
 bad=[p for p,h in hashes.items() if hashlib.sha256(local_path(p).read_bytes()).hexdigest()!=h];assert not bad
 source_checks[kind]={'files':len(hashes),'mismatches':bad}
 for c in d['cases']:
  rv=next(x for x in review[kind] if x['case_id']==c['case']['id']);assert len(rv['turns'])==len(c['profile']['turns'])
  assert len(c['observations'])==len(c['profile']['turns'])
  for t,o,rt in zip(c['profile']['turns'],c['observations'],rv['turns']):
   assert t['prompt']==o['prompt']
   if 'response' in o: assert t['response']==o['response']
   if 'prompt_sha256' in o: assert hashlib.sha256(o['prompt'].encode()).hexdigest()==o['prompt_sha256']
   assert o.get('capture_error') is None
   if not t['success']: assert rt['verdict']=='unassessed'
   assert t['metrics']['model_call_count']==len(t['metrics']['model_calls'])
assert reports['adaptive']['plan']==json.loads((D/'cs35l-adaptive-plan-20261018.json').read_text())
for cmd in [['git','diff','--exit-code','484305f','--','src','scripts','tests','pyproject.toml','uv.lock'],['git','diff','--check']]:subprocess.run(cmd,cwd=ROOT,check=True,capture_output=True)
docs=[ROOT/'docs/cs35l-tutoring-evaluation.md',ROOT/'docs/superpowers/specs/2026-10-18-tutoring-quality-alternatives-design.md'];docchecks=[]
for p in docs:
 s=p.read_text();assert 'Results will be filled' not in s
 assert not any(l.rstrip()!=l for l in s.splitlines())
 for link in re.findall(r'\]\(([^)]+)\)',s):
  if not re.match(r'\w+://',link) and not link.startswith('#'):assert (p.parent/link.split('#')[0]).resolve().exists(),link
 docchecks.append({'path':str(p.relative_to(ROOT)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'local_links_exist':True,'trailing_whitespace':False})
artifacts={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(D.glob('cs35l-*.json')) if p.name!='cs35l-verification-v1.json'}
result={'status':'passed','limits':'Verification of captured identities, counts, hashes and document consistency; not independent pedagogical adjudication. Remote server postcheck is retained separately within this record after collection.','source_checks':source_checks,'repeat_checks':repeat_checks,'documents':docchecks,'artifacts_sha256':artifacts,'production_diff_from_484305f':'empty','runner_source':Path(__file__).read_text()}
(D/'cs35l-verification-v1.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k not in ['runner_source','artifacts_sha256']},indent=2))
